begin;

do $$
declare
  v_sector uuid;
  v_category uuid;
  v_body jsonb;
  v_text text;
  v_id uuid;
begin
  select id into v_sector from public.sectors where slug='addiction-recovery';
  select id into v_category from public.categories where slug='addiction-recovery-core' and sector_id=v_sector;
  if v_sector is null or v_category is null then raise exception 'addiction sector or core category missing'; end if;

  v_body := jsonb_build_object('blocks', jsonb_build_array(
    jsonb_build_object('type','paragraph','text','هذا القطاع ليس قائمة مواد أو أعراض، بل خريطة عربية متكاملة لفهم اضطرابات استخدام المواد والسلوكيات الإدمانية واتخاذ الخطوة المناسبة بحسب الحاجة. قد يصل المستخدم وهو يبحث عن معنى عرض انسحاب، أو لأن أحد أفراد الأسرة تغير سلوكه، أو لأن مختصًا يريد مقارنة خيارات العلاج، أو لأن مؤسسة تبني برنامج وقاية، أو لأن شخصًا خرج للتو من الطوارئ ويحتاج مسار متابعة. لذلك صُممت المنظومة على مبدأ واحد: لا تجبر القارئ على البدء من صفحة عامة ثم البحث عشوائيًا، بل توجهه من مستوى الخطر والسؤال الحالي إلى المسار الأكثر صلة، مع إبقاء المحتوى الطبي الفردي للفرق المؤهلة.'),
    jsonb_build_object('type','paragraph','text','يضم المرجع مسارات مترابطة للحالات الأساسية، إدارة الانسحاب، العلاج واختيار مستوى الرعاية، خفض الضرر والجرعة الزائدة، التعافي المستمر، الأسرة، الوقاية والتدخل المبكر، المجتمع والخدمات، الفئات ذات الاحتياجات الخاصة، والأدلة والمنهجية. كما يرتبط بموسوعة المواد والأطلس التفاعلي والمقارنات والتداخلات والانتشار والوفيات. قيمة هذه البنية ليست في كثرة الصفحات وحدها، بل في أن كل طبقة تؤدي وظيفة مختلفة ولا تكرر الأخرى: صفحة المادة تشرح المادة، صفحة الحالة تشرح الاضطراب، صفحة العلاج تشرح القرار العلاجي، وصفحة الأسرة تشرح ما يمكن للأسرة فعله دون أن تتحول إلى فريق طبي.'),

    jsonb_build_object('type','heading','level',2,'text','1. ابدأ بالسؤال لا باسم المادة'),
    jsonb_build_object('type','paragraph','text','من السهل أن يتحول البحث عن الإدمان إلى مطاردة أسماء: ما هو الفنتانيل؟ ما الفرق بين الكوكايين والميثامفيتامين؟ هل الترامادول يسبب اعتمادًا؟ لكن الاسم وحده لا يحدد الخطوة. إذا كان السؤال عن فقدان وعي أو اضطراب تنفس أو تسمم حاد، فالمسار الأول هو الطوارئ والسلامة. إذا كان السؤال عن توقف مادة وظهور أعراض، فالمسار هو الانسحاب وتقدير الحاجة إلى رعاية. إذا كان الاستخدام مستمرًا ويؤثر في الوظيفة أو السيطرة، فالمسار هو التقييم والعلاج. وإذا كان الشخص غير مستعد للتوقف لكنه معرض لجرعة زائدة أو عدوى أو أضرار أخرى، فمسار خفض الضرر يبقى ضروريًا.'),
    jsonb_build_object('paragraph','paragraph'),
    jsonb_build_object('type','paragraph','text','هذا المنطق يمنع خطأ شائعًا: قراءة صفحة مادة مفصلة ثم محاولة تحويل المعرفة إلى تشخيص أو خطة علاج فردية. الموسوعة تساعد على الفهم والمقارنة، لكنها لا تعرف عمر الشخص وحمله وأمراضه وأدويته ونمط الاستخدام والصحة النفسية والسكن وتاريخ الجرعات الزائدة. لذلك كلما انتقل السؤال من ما هذه المادة؟ إلى ماذا أفعل لهذا الشخص؟ يجب أن ينتقل القارئ من طبقة المعلومات إلى طبقة التقييم والرعاية.'),

    jsonb_build_object('type','heading','level',3,'text','أسئلة تحدد نقطة الدخول'),
    jsonb_build_object('type','list','ordered',true,'items',jsonb_build_array(
      'هل توجد مشكلة فورية في الوعي أو التنفس أو السلامة أو خطر إيذاء النفس؟',
      'هل ظهرت أعراض بعد تقليل أو إيقاف مادة أو دواء؟',
      'هل هناك فقدان سيطرة أو ضرر متكرر أو تراجع في الدراسة أو العمل أو العلاقات؟',
      'هل السؤال عن علاج أو دواء أو مركز أو مستوى رعاية؟',
      'هل المشكلة الأساسية هي جرعات زائدة أو عدوى أو انقطاع متكرر عن الخدمات؟',
      'هل الأسرة تحتاج طريقة للتواصل ووضع حدود ودعم العلاج؟',
      'هل المطلوب منع المشكلة قبل بدايتها أو التدخل عند مؤشرات مبكرة؟',
      'هل توجد احتياجات خاصة مرتبطة بالعمر أو الحمل أو الإعاقة أو السكن أو مرض مزمن؟'
    )),

    jsonb_build_object('type','heading','level',2,'text','2. الطوارئ والانسحاب: افصل بين المعرفة والتصرف الآمن'),
    jsonb_build_object('type','paragraph','text','يحتوي القطاع على صفحات للانسحاب والحالات المرتبطة بالمواد، لكن وجود هذه المعلومات لا يجعل الانسحاب المنزلي خيارًا مناسبًا لكل حالة. بعض المواد يمكن أن تنتج أعراضًا خطرة أو معقدة، كما قد توجد أمراض جسدية أو نفسية أو أدوية أخرى تغير القرار. لذلك يستخدم المرجع لغة تفرق بين معرفة الأعراض الشائعة وبين تحديد من يحتاج رعاية عاجلة أو متابعة طبية. لا يقدم القطاع جداول جرعات أو وصفات ذاتية لإيقاف المواد، لأن ذلك يتجاوز وظيفة المرجع وقد يكون غير آمن.'),
    jsonb_build_object('type','paragraph','text','عند الاشتباه بتسمم أو جرعة زائدة، لا يحتاج المستخدم إلى إثبات نوع المادة قبل طلب خدمات الطوارئ المحلية. وبعد انتهاء الأزمة، لا ينبغي أن ينتهي المسار عند الاستقرار الجسدي. لحظة الخروج فرصة لإعادة تقييم السبب، تاريخ الجرعات الزائدة، وجود اضطراب استخدام، الصحة النفسية، الأدوية، والسكن والدعم، ثم ربط الشخص بالعلاج أو خفض الضرر أو المتابعة المناسبة. هذا الانتقال من الحدث الحاد إلى الرعاية المستمرة أحد المحاور التي يربطها القطاع عمدًا.'),

    jsonb_build_object('type','heading','level',2,'text','3. التقييم: لا تختزل الاضطراب في كمية الاستخدام'),
    jsonb_build_object('type','paragraph','text','كمية المادة وتكرارها مهمان، لكن التشخيص والشدة لا يختزلان في رقم واحد. يهم أيضًا فقدان السيطرة، الرغبة، استمرار الاستخدام رغم الضرر، أثره في الوظيفة، محاولات التوقف، التحمل والانسحاب بحسب الحالة، والوقت الذي يستهلكه السلوك. وتهم المصاحبات: الاكتئاب والقلق والذهان والصدمات والألم والنوم والأدوية والأمراض الجسدية. كما أن العمر والحمل والسكن والقانون والموارد تغير طريقة الاستجابة. لهذا تعرض صفحات القطاع أدوات فهم ولا تقدم نتيجة تشخيصية من إجابة منفردة.'),
    jsonb_build_object('type','paragraph','text','التقييم الجيد قابل للمراجعة. قد تظهر الأعراض النفسية أثناء التسمم أو الانسحاب ثم تتغير، وقد يتضح بعد أسابيع أن اضطرابًا نفسيًا مستقلًا يحتاج علاجًا. وقد يبدأ الشخص في مستوى رعاية ثم يحتاج تصعيدًا أو تخفيفًا. المرجع لذلك يكرر فكرة القياس والمتابعة بدل اتخاذ قرار ثابت من الزيارة الأولى. الغرض هو زيادة دقة الأسئلة التي تُطرح على الفريق، لا تحويل المستخدم إلى بديل عن الفريق.'),

    jsonb_build_object('type','heading','level',3,'text','متى تنتقل من الفهم إلى التقييم المهني؟'),
    jsonb_build_object('type','paragraph','text','يصبح التقييم المهني أكثر أهمية عندما يتكرر الضرر، أو يفشل الشخص في تنفيذ هدفه رغم المحاولات، أو تظهر أعراض انسحاب أو جرعات زائدة أو استخدام مواد متعددة، أو تتدهور الدراسة أو العمل أو العلاقات، أو توجد أعراض نفسية شديدة، أو يكون الشخص حاملًا أو صغير السن أو كبير السن أو لديه أمراض وأدوية متعددة. كل واحدة من هذه الحالات لا تحدد العلاج مسبقًا، لكنها تزيد قيمة تقييم منظم يربط الشدة بالمخاطر والخيارات.'),

    jsonb_build_object('type','heading','level',2,'text','4. العلاج: اختر ما تدعمه الأدلة للحالة المحددة'),
    jsonb_build_object('type','paragraph','text','لا يوجد علاج واحد للإدمان كفئة عامة. بعض اضطرابات استخدام المواد لديها علاجات دوائية قوية الدليل، مثل اضطراب استخدام الأفيونات حيث تؤكد منظمة الصحة العالمية أهمية العلاج الصياني بناهضات الأفيون ضمن رعاية منظمة، بينما توجد خيارات دوائية وسلوكية مثبتة أيضًا للكحول والتبغ في سياقات مناسبة. وفي اضطرابات أخرى، يكون العلاج النفسي والسلوكي ومعالجة المصاحبات محورًا أكبر. لذلك يخصص القطاع مرجعًا مستقلًا للعلاج المبني على الدليل بدل توزيع أسماء الأدوية على صفحات متفرقة.'),
    jsonb_build_object('type','paragraph','text','اختيار العلاج يتضمن أيضًا اختيار مستوى الرعاية. الإقامة ليست أفضل لمجرد أنها أكثر كثافة، والرعاية الخارجية ليست أفضل لمجرد أنها أقل تقييدًا. القرار يتعلق بخطر الانسحاب والتسمم، الاستقرار النفسي والطبي، القدرة على حماية النفس، السكن والدعم، إمكانية المتابعة، وتاريخ الانقطاع عن العلاج. كما أن جودة مقدم الخدمة تقاس بالترخيص والكفاءة والتقييم والعلاج المناسب والمصاحبات والخصوصية والاستمرارية والنتائج، لا بالفخامة أو نسبة نجاح تسويقية غير معرفة.'),

    jsonb_build_object('type','heading','level',3,'text','ما الذي تقيسه أثناء العلاج؟'),
    jsonb_build_object('type','paragraph','text','قد يكون الامتناع هدفًا أساسيًا، لكنه ليس المؤشر الوحيد. يمكن أن تشمل النتائج البقاء في العلاج، انخفاض الجرعات الزائدة والطوارئ، تحسن الصحة والنوم والمزاج، استقرار السكن، العودة إلى الدراسة أو العمل، انخفاض السلوكيات الخطرة، تحسن العلاقات، والقدرة على طلب المساعدة مبكرًا. الصفحة العلاجية في القطاع تشرح كيف تُراجع هذه المؤشرات وكيف تتحول العودة للاستخدام من حكم على الشخص إلى معلومة قد تستدعي تعديل الخطة.'),

    jsonb_build_object('type','heading','level',2,'text','5. خفض الضرر: احمِ الحياة واستمر في فتح باب العلاج'),
    jsonb_build_object('type','paragraph','text','خفض الضرر ليس موقفًا مضادًا للتعافي ولا موافقة على الاستخدام. هو مجموعة تدخلات تقلل الوفاة والعدوى والإصابات والأضرار وتربط الشخص بخدمات صحية واجتماعية، سواء كان مستعدًا للتوقف الآن أم لا. المرجع المخصص لهذا المسار يشرح الوقاية من الجرعة الزائدة على مستوى النظام، الوصول إلى خدمات النالوكسون وفق البرامج والقوانين المحلية، العلاج الفعال لاضطراب استخدام الأفيونات، الوقاية والفحص والعلاج للعدوى، الخدمات منخفضة العتبة، الأقران، الحقوق، والانتقال بعد الطوارئ.'),
    jsonb_build_object('type','paragraph','text','أهمية هذا المسار تظهر عندما يكون نموذج إما الامتناع أو لا خدمة سببًا في فقدان الناس. الشخص الذي لم يصل بعد إلى هدف الامتناع ما يزال قادرًا على خفض خطر قاتل، إجراء فحص، معالجة عدوى، بدء علاج، تثبيت سكن، أو البقاء متصلًا بفريق. والعكس صحيح: الشخص في تعافٍ مستقر قد يبقى مستفيدًا من بعض عناصر خفض الضرر خلال انتقالات عالية الخطورة. القطاع يعامل المسارين بوصفهما قابلين للتكامل بدل المنافسة.'),

    jsonb_build_object('type','heading','level',2,'text','6. التعافي: عملية وظيفية ممتدة لا يوم خروج'),
    jsonb_build_object('type','paragraph','text','التعافي قد يتضمن الامتناع أو خفض الضرر بحسب المرحلة والهدف، لكنه يتسع ليشمل الصحة والهوية والعلاقات والسكن والعمل أو الدراسة والمعنى والقدرة على مواجهة الأزمات. لهذا لا يضع القطاع نهاية رمزية عند اكتمال برنامج علاجي. توجد صفحات للتعافي المستمر وخطط المتابعة ومنع العودة للضرر ودعم الأسرة والروتين والنوم والاندماج الوظيفي. الفكرة المركزية هي أن الاستقرار يُبنى في الحياة اليومية، وليس داخل الجلسة فقط.'),
    jsonb_build_object('type','paragraph','text','عودة عرض أو استخدام لا تعيد الشخص تلقائيًا إلى نقطة الصفر. قد تكشف تغيرًا في المحفزات أو الصحة النفسية أو الدواء أو السكن أو شبكة الدعم أو مستوى الرعاية. لذلك تراجع الخطة: ما الذي تغير قبل الحدث؟ ما المخاطر الجديدة؟ هل انقطع الاتصال بالخدمة؟ هل ظهر اضطراب غير معالج؟ ما التدخل الذي يمكن تعديله؟ هذا المنهج أكثر فائدة من تفسير كل تعثر بوصفه فشل إرادة أو فشلًا نهائيًا للعلاج.'),

    jsonb_build_object('type','heading','level',2,'text','7. الأسرة: ادعم دون أن تتحول إلى مراقب أو معالج'),
    jsonb_build_object('type','paragraph','text','الأسرة قد تكون أحد أقوى عوامل الحماية، لكنها يمكن أن تتعب أو تدخل في أنماط إنقاذ أو صراع أو سيطرة تجعل الجميع أقل قدرة على اتخاذ قرارات جيدة. مسار الأسرة في القطاع يركز على التواصل، الحدود، السلامة، دعم الوصول إلى العلاج، التعامل مع المال والسكن بحسب الحاجة، متابعة ما بعد الطوارئ، العنف والسيطرة، ورفاه مقدم الرعاية. لا يطلب من الأسرة إدارة الانسحاب أو وصف العلاج أو مراقبة الشخص على مدار الساعة.'),
    jsonb_build_object('type','paragraph','text','الخصوصية والموافقة مهمتان. وجود الأسرة في المنزل أو دفعها التكلفة لا يمنحها تلقائيًا كل تفاصيل علاج شخص بالغ، كما أن السرية لا تعني استبعاد الأسرة دائمًا. يمكن الاتفاق مع الشخص على ما يُشارك ومن يشارك وكيف، مع مراعاة القانون المحلي وأمان العلاقة. إذا كان هناك عنف أو تهديد أو استغلال، تتغير الأولويات ولا يكون إشراك جميع الأطراف في جلسة واحدة خطوة محايدة.'),

    jsonb_build_object('type','heading','level',3,'text','سؤال الأسرة الأكثر فائدة'),
    jsonb_build_object('type','paragraph','text','بدل السؤال كيف أجعله يتوقف؟ ابدأ بسؤالين: ما الخطر الذي نستطيع تقليله الآن؟ وما الخطوة التي تزيد احتمال بقاء الشخص متصلًا بالمساعدة؟ قد يكون الجواب تقييمًا طبيًا، موعد علاج، خطة بعد طوارئ، حدًا ماليًا واضحًا، حماية طفل، دعمًا لمقدم الرعاية، أو تواصلًا أقل صدامًا. هذه الأسئلة لا تلغي الهدف طويل المدى، لكنها تحول القلق إلى قرارات قابلة للتنفيذ.'),

    jsonb_build_object('type','heading','level',2,'text','8. الوقاية والتدخل المبكر: لا تنتظر الاضطراب الكامل'),
    jsonb_build_object('type','paragraph','text','مرجع الوقاية في هذا القطاع مبني على المعايير الدولية التي تفرق بين مراحل العمر والبيئات وتجمع الأسرة والمدرسة والمجتمع والسياسات. لا يعتبر نشر معلومات عن أضرار المواد وحده برنامجًا وقائيًا كافيًا، ولا يعتمد على التخويف. يركز على المهارات الأسرية والاجتماعية، المناخ المدرسي، الصحة النفسية، عوامل الحماية، الحد من التسويق والتوفر وفق الأنظمة، والقدرة على اكتشاف المشكلات مبكرًا وربطها بخدمة مناسبة.'),
    jsonb_build_object('type','paragraph','text','التدخل المبكر مهم عندما يبدأ ضرر أو تراجع وظيفي قبل وصول الحالة إلى شدة عالية. يمكن أن يكون حوارًا منظمًا أو فحصًا مناسبًا في سياق صحي أو إحالة، بشرط وجود خطة لما بعد النتيجة. لا ينبغي استخدام أدوات الفحص كتشخيص أو عقوبة. إذا ظهرت مؤشرات شدة أعلى، ينتقل الشخص إلى العلاج بدل إبقائه في برنامج وقائي غير كافٍ. بهذا تظل الحدود بين الوقاية والعلاج عملية وقابلة للحركة.'),

    jsonb_build_object('type','heading','level',2,'text','9. الفئات والاحتياجات الخاصة: عدل الوصول لا معيار الجودة'),
    jsonb_build_object('type','paragraph','text','المراهق ليس بالغًا صغيرًا، والحمل ليس ظرفًا ثانويًا، وكبير السن قد تكون لديه أدوية وسقوط وأمراض تغير الخطر، والشخص ذو الاحتياجات الخاصة قد يحتاج تواصلًا ميسرًا أو دعم قرار، ومن لا يملك سكنًا قد لا يستطيع تنفيذ خطة تفترض هاتفًا وعنوانًا ثابتين. لذلك يجمع القطاع مسارًا للفئات والاحتياجات الخاصة حتى لا تبقى هذه التعديلات ملاحظات هامشية داخل صفحات عامة.'),
    jsonb_build_object('type','paragraph','text','تكييف الرعاية لا يعني تقديم مستوى علمي أقل. يعني إزالة حواجز لا علاقة لها بفعالية العلاج: لغة معقدة، مبنى غير متاح، موعد لا يناسب النقل، غياب مترجم أو تواصل بديل، سياسة لا تراعي الحمل أو مسؤولية رعاية طفل، أو خطة دواء لا تراعي تعدد الأدوية. يجب أن تبقى السلامة والكرامة والخصوصية والدليل أساسًا، ثم تتغير طريقة الوصول والتواصل والتنفيذ.'),

    jsonb_build_object('type','heading','level',2,'text','10. المجتمع والمنظومات: جودة الإحالة تقاس بالوصول لا بإرسال الرابط'),
    jsonb_build_object('type','paragraph','text','يمكن أن توجد في المدينة خدمات ممتازة ويظل النظام ضعيفًا إذا لم يعرف الناس كيف ينتقلون بينها. الطوارئ والرعاية الأولية والصحة النفسية وعلاج الإدمان وخدمات العدوى ودعم الأقران والسكن والمدرسة والعمل تحتاج مسارات إحالة ومسؤوليات واضحة. الإحالة الناجحة ليست كتابة اسم جهة؛ هي وصول الشخص إلى الخدمة التالية في وقت مناسب، مع المعلومات الضرورية ومتابعة ما إذا اكتمل الانتقال.'),
    jsonb_build_object('type','paragraph','text','مسار المجتمع والخدمات يجمع ما يخص دعم الأقران، الرعاية المجتمعية، المؤسسات، تدريب العاملين، خفض الوصمة، العمل والتعليم، وقياس الوصول. كما يساعد الجهات على التفكير في نقاط التسرب: من يصل إلى التقييم ولا يبدأ العلاج؟ من يخرج من الطوارئ ولا يتابع؟ من يبدأ دواءً ثم ينقطع؟ من لا يصل أصلًا بسبب موقع أو تكلفة أو لغة أو وصمة؟ تحسين هذه النقاط قد يحقق أثرًا أكبر من إضافة برنامج جديد لا يتصل ببقية النظام.'),

    jsonb_build_object('type','heading','level',2,'text','11. الأطلس والمقارنات: أدوات فهم وليست أدوات تجربة'),
    jsonb_build_object('type','paragraph','text','الأطلس التفاعلي للمواد صُمم ليجيب عن أسئلة بحث حقيقية: الاسم العربي والإنجليزي، الفئة، التأثيرات والمخاطر، الوضع العلاجي، ومصادر موثوقة. وتضيف المقارنات طبقة مفيدة لفهم الفروق بين مواد قد يخلط بينها الناس، بينما تعرض صفحات التداخلات مستوى مخاطر عام. الغرض هو تقليل الالتباس وتحسين الحوار مع المختصين، لا مساعدة القارئ على اختيار مادة أو خلط مواد أو تعديل جرعة للحصول على تأثير معين.'),
    jsonb_build_object('type','paragraph','text','لهذا تحافظ المنظومة على حدود واضحة: لا جداول جرعات للاستخدام غير الطبي، لا وصفات خلط، لا طرق تصنيع أو إخفاء، لا إرشادات تجعل الاستخدام أكثر كفاءة. عندما تكون المعلومة التفصيلية مفيدة لفهم الخطر أو العلاج، تُعرض في هذا السياق. وعندما تتحول إلى تعليمات قابلة للتنفيذ لرفع الخطر، لا تكون جزءًا من وظيفة المرجع. هذه الحدود تحافظ على القيمة العلمية دون تحويل المعرفة إلى أداة ضرر.'),

    jsonb_build_object('type','heading','level',2,'text','12. كيف نقرأ قوة الدليل وحداثته؟'),
    jsonb_build_object('type','paragraph','text','لا تتساوى المصادر. يعطي القطاع أولوية للإرشادات الرسمية الحديثة، المعايير الدولية، المراجعات المنهجية، والجهات الصحية والتنظيمية الموثوقة، ثم يستخدم الدراسات الفردية عندما تضيف سؤالًا جديدًا أو تفصيلًا لا تغطيه المراجع الأعلى. وجود دراسة حديثة لا يعني تلقائيًا أنها تغير الممارسة؛ يجب النظر إلى التصميم والحجم والتكرار واتساق النتائج وقابلية التطبيق. لذلك تُفصل النتائج الناشئة عن التوصيات المستقرة قدر الإمكان.'),
    jsonb_build_object('type','paragraph','text','الحداثة مهمة خصوصًا في المواد الاصطناعية الجديدة، المنتجات النيكوتينية، أنماط السوق، التسويق الرقمي، والوفيات والانتشار. أما بعض المبادئ العلاجية والوقائية فقد تستند إلى إرشادات أقدم ما تزال مرجعية إذا لم تُستبدل. سياسة المراجعة هي فحص تاريخ المصدر والإصدار، البحث عن تحديثات، وتسجيل ما بُني عليه الادعاء المهم. الهدف ألا يبدو المحتوى حديثًا بسبب تاريخ الصفحة بينما تستند أهم قراراته إلى معلومات تجاوزتها الإرشادات.'),

    jsonb_build_object('type','heading','level',2,'text','13. كيف تستخدم هذا القطاع كفرد أو أسرة أو مختص؟'),
    jsonb_build_object('type','paragraph','text','للفرد: ابدأ بالسؤال الذي يصف حاجتك الحالية، ثم انتقل من السلامة إلى التقييم والعلاج أو خفض الضرر والتعافي. للأسرة: ابدأ بمسار الأسرة، لكن افتح صفحات الانسحاب والطوارئ عندما توجد علامات خطر وصفحات العلاج عندما تبحث عن خدمة. للمختص: استخدم صفحات الأدلة والأطلس والمقارنات والحالات المتخصصة لتوسيع التثقيف والإحالة، مع العودة إلى الإرشادات الأصلية عند القرار السريري. للمؤسسة: ابدأ بالوقاية أو المجتمع والخدمات والأدلة، ثم حول المحتوى إلى سياسات ومسارات قابلة للقياس بدل نسخ النصوص إلى بروشور.'),
    jsonb_build_object('type','paragraph','text','إذا لم تجد إجابة، فهذه ليست دعوة إلى استنتاجها من صفحة قريبة. ابحث عن فجوة محددة: هل السؤال يتعلق بمادة جديدة؟ فئة عمرية؟ تداخل؟ مسار خدمة؟ قانون محلي؟ نتيجة علاج؟ ثم تُضاف الصفحة فقط إذا كانت تقدم وظيفة مستقلة ومصادر كافية ولا تكرر محتوى قائمًا. بهذه القاعدة ينمو المرجع أفقيًا وعموديًا دون أن يصبح أرشيفًا ضخمًا من العناوين المتشابهة.'),

    jsonb_build_object('type','heading','level',2,'text','14. معيار اكتمال المرجع: اتصال المسارات لا عدد الصفحات'),
