        jsonb_build_object('claim','المحتوى المرجعي لا يحل محل الرعاية الطبية الفردية في الطوارئ أو العلاج','sources',jsonb_build_array('WHO-UNODC Treatment Standards 2020','WHO opioid update 2026'))
