    jsonb_build_array(
      jsonb_build_object('title','International Standards for the Treatment of Drug Use Disorders','publisher','WHO and UNODC','year',2020,'url','https://www.who.int/publications/i/item/international-standards-for-the-treatment-of-drug-use-disorders','source_type','guideline','authority_tier','primary'),
      jsonb_build_object('title','WHO updates guidelines on opioid dependence treatment and overdose prevention','publisher','World Health Organization','year',2026,'url','https://www.who.int/news/item/02-04-2026-who-updates-guidelines-on-opioid-dependence-treatment-and-overdose-prevention','source_type','guideline','authority_tier','primary'),
      jsonb_build_object('title','Needle and syringe programmes for people who inject drugs: operational guide','publisher','World Health Organization','year',2026,'url','https://www.who.int/publications/i/item/9789240116214','source_type','guideline','authority_tier','primary'),
      jsonb_build_object('title','International Standards on Drug Use Prevention, Second updated edition','publisher','UNODC and World Health Organization','year',2018,'url','https://www.unodc.org/documents/prevention/UNODC-WHO_2018_prevention_standards_E.pdf','source_type','guideline','authority_tier','primary'),
      jsonb_build_object('title','Implementing what works in alcohol policy: progress report on the SAFER initiative','publisher','World Health Organization','year',2026,'url','https://www.who.int/publications/i/item/9789240120587','source_type','guideline','authority_tier','primary'),
      jsonb_build_object('title','MPOWER','publisher','World Health Organization','year',2026,'url','https://www.who.int/initiatives/mpower/','source_type','official-definition','authority_tier','primary'),
