      jsonb_build_object('title','WHO clinical treatment guideline for tobacco cessation in adults','publisher','World Health Organization','year',2024,'url','https://www.who.int/publications/i/item/9789240096431','source_type','guideline','authority_tier','primary')
    ),null
  ) on conflict(slug) do nothing returning id into v_id;

  if v_id is null then select id into v_id from public.content where slug='addiction-recovery-sector-editorial'; end if;
  if not exists(select 1 from public.content where id=v_id and status='published') then update public.content set status='published',robots_index=false,robots_follow=true,published_at=now() where id=v_id; end if;
  insert into public.content_categories(content_id,category_id,is_primary) values(v_id,v_category,true) on conflict(content_id,category_id) do update set is_primary=true;

  update public.sectors
  set editorial_content_id=v_id,
      metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('editorial_model','unique-noindex-sector-guide-v1','editorial_updated_at','2026-08-28'),
      updated_at=now()
  where id=v_sector;
